def lfu_cache(maxsize=128, typed=False):
    '''Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    '''

    def __init__(self, func):
        self.func = func
        self.cache = dict()
        self.last_usage = dict()
        self.maxsize = maxsize
        self.typed = typed

    def __call__(self, *args):
        key = self.make_key(args)
        if key in self.cache:
            del self.last_usage[key]
            self.last_usage[key] = len(self.last_usage)
            return self.cache[self.make_key(args)]
        else:
            self.cache[self.make_key(args)] = self.func(*args)
            self.last_usage[self.make_key(args)] = len(self.last_usage)
            if len(self.cache) > self.maxsize:
                oldest_value = min(self.last_usage, key=self.last_usage.get)
                del self.cache[oldest_value]
                del self.last_usage[oldest_value]
            return self.cache[self.make_key(args)]

    def clear(self):
        self.cache = dict()
        self.last_usage = dict()

    def __len__(self):
        return len(self.cache)

    def remove(self, *args):
        key = self.make_key(args)
        if key in self.cache:
            del self.cache[key]

    def make_key(self, args):
        if self.typed:
            args = list(args)
            for i, arg in enumerate(args):
                if type(arg) in (list, tuple):
                    args[i] = tuple(arg)
                elif type(arg) is dict:
                    args[i] = tuple(sorted(arg.items()))
            args = tuple(args)
        return hash(args)

