def integral(bins, edges):
    if not bins:
        raise ValueError("Bins must be provided")
    if not edges:
        raise ValueError("Edges must be provided")
    area = 0
    for i in range(len(bins)):
        area += (edges[i+1]-edges[i]) * bins[i]
    return area

