def fix_namespace_prefix_w(content):
    # Split the content by newlines
    lines = content.split("\n")

    # Loop through each line and replace the `w:st` prefix with `w-st`
    for i in range(len(lines)):
        # Check if the line contains the `w:st` prefix
        if lines[i].startswith("w:st"):
            # Replace the prefix with `w-st`
            lines[i] = lines[i].replace("w:st", "w-st")

    # Join the lines back into a single string and return it
    return "\n".join(lines)

