                        # Check if the line starts with "0=" and ends with "T"
                        if line.startswith("0=") and line.endswith("T"):
                            # If the line is "0=C T", then the directory is an OCFL Storage Root
                            if line == "0=C T":
                                result = "root"
                            # If the line is "0=O T", then the directory is an OCFL Object
                            elif line == "0=O T":
