def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("number must be an integer, got {}".format(type(number)))
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list of strings, got {}".format(type(alphabet)))
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be an integer, got {}".format(type(padding)))

    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one string")

    strings = []
    while number > 0:
        number, remainder = divmod(number, len(alphabet))
        strings.append(alphabet[remainder])

    if padding is not None and padding > len(strings):
        for _ in range(padding - len(strings)):
            strings.append(" ")

    return "".join(reversed(strings))

