def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.

    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (set, list, tuple, range, "".__class__, "".__class__)):
        # For sets, lists, tuples, ranges, and strings, return whether the item is hashable / convertible to the below types
        return seq, seq.__class__.__name__
    if isinstance(seq, dict):
        # For dictionaries, check whether the values are hashable / convertible to the below types
        items = []
        for item in seq.values():
            if isinstance(item, (set, list, tuple, range, "".__class__, "".__class__)):
                items.append((item, item.__class__.__name__))
            else:
                raise ValueError("Dictionary values should be of types 'set', 'list', 'tuple', 'range', or 'str'.")
        return items, "dict"
    if isinstance(seq, (int, float, complex, str)):
        # For integers, floats, complex numbers, and strings, return whether the item is hashable / convertible to the below types
        return seq, seq.__class__.__name__
    if hasattr(seq, "__iter__"):
        # For any iterable object, catch the TypeError and return a (sequence, type) pair
        try:
            return iter(seq), seq.__class__.__name__
