def hist_to_graph(hist, make_value=None, get_coordinate="left",
                 field_names=("x", "y"), scale=None):
    if not isinstance(hist, histogram):
        raise TypeError("hist must be a histogram")
    if make_value is None:
        make_value = lambda bin_: bin_
    if not callable(make_value):
        raise TypeError("make_value must be a function")
    if not (get_coordinate in ["left", "right", "middle"]):
        raise ValueError("get_coordinate must be either 'left', 'right', or 'middle'")
    if not (isinstance(field_names, tuple) and len(field_names) == 2):
        raise ValueError("field_names must be a tuple of length 2")
    if scale is not None and not isinstance(scale, (tuple, list)):
        raise ValueError("scale must be an iterable")

    # Convert bins to points
    points = []
    for i, bin_ in enumerate(hist):
        point = {"index": i}
        if get_coordinate == "left":
            point[field_names[0]] = bin_.left
            point[field_names[1]] = make_value(bin_)
        elif get_coordinate == "right":
            point[field_names[0]] = bin_.right
            point[field_names[1]] = make_value(bin_)
        else:
            point[field_names[0]] = (bin_.left + bin_.right) / 2
            point[field_names[1]] = make_value(bin_)
        points.append(point)

    # Create graph
    graph = Graph(points, field_names=field_names)
    if scale is not None:
        graph.scale = scale
    return graph

