def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    with open(yaml_file, 'r') as f:
        try:
            data = yaml.safe_load(f.read())
        except yaml.YAMLError as e:
            raise IRValidatorException("Error parsing YAML file: " + str(e))
    mandatory_fields = ["key_1_name", "key_2_name", "key_3_name", "key_4_name"]
    missing_fields = []
    for field in mandatory_fields:
        if not field in data:
            missing_fields.append(field)
    if missing_fields:
        raise IRValidatorException("The following mandatory fields are missing from the YAML file: " + ", ".join(missing_fields))
    return data

